// SilkNX runtime: object model and services for BepInEx mods translated to native Switch code.
//
// Translated mods are C++ generated by tools/silkport. They manipulate real IL2CPP objects (game objects,
// strings, arrays, delegates) directly, and represent their own classes as managed object[] arrays so the
// game's garbage collector sees and scans them.
#pragma once

#include "silk.h"
#include "rt_game.h"

typedef struct Il2CppObject *obj;

struct Il2CppObject {
    void *klass;
    void *monitor;
};

struct Il2CppArray : Il2CppObject {
    void *bounds;
    uintptr_t max_length;
};

struct Il2CppString : Il2CppObject {
    int32_t length;
    char16_t chars[1];
};

// ---------------------------------------------------------------- generated tables

struct rt_vmap_entry {
    uint32_t id;
    void *fn;
};

// Unity messages, in the order of rt_modtype::messages.
enum rt_message {
    MSG_Awake, MSG_Start, MSG_OnEnable, MSG_OnDisable, MSG_OnDestroy, MSG_Update, MSG_LateUpdate,
    MSG_FixedUpdate, MSG_OnGUI, MSG_OnApplicationQuit, MSG_COUNT
};

// Descriptor of a mod-defined type.
struct rt_modtype {
    const char *name;
    rt_modtype *base;
    uint32_t size;    // sizeof the C++ struct (including the object[] header)
    int32_t emu;      // 0 object, 1 component, 2 plugin, 3 exception, 4 delegate
    bool is_vt;
    void *cctor;
    uint32_t statics_size;
    void *statics;
    bool cctor_done;
    const rt_vmap_entry *vmap;
    uint32_t nvmap;
    const uint32_t *ifaces;  // 0-terminated interface ids
    void *messages[MSG_COUNT];
    void *ctor;  // parameterless instance constructor (or null)
    int32_t asm_index;
};

struct rt_literal {
    const char16_t *s;
    uint32_t len;
};

struct rt_typeref {
    const char *aqn;      // game type: assembly-qualified name for Type.GetType
    rt_modtype *desc;     // mod type
    uint32_t raw;
    const char *name;     // for diagnostics
};

struct rt_blob {
    const uint8_t *data;
    uint32_t size;
};

struct rt_vsite {
    uint32_t mid;
    int32_t slot;
    int32_t tref;
    bool iface;
    const char *name;
    const char *desc;
    // cache
    void *klass;
    void *fp;
    const void *mi;
};

struct rt_rsite {
    const char *desc;  // "owner aqn|name|param aqns;...|generic arg aqns;...|i/s"
    void *fp;
    const void *mi;
};

struct rt_patch_class {
    int32_t asm_index;
    rt_modtype *desc;
    bool applied;
};

struct rt_plugin {
    const char *guid, *name, *version, *folder;
    rt_modtype *desc;
    void *ctor;
    int32_t asm_index;
};

struct rt_romfs_file {
    const char *path;  // relative to the romfs root, '/' separated
    uint64_t size;
};

extern "C" {
extern const rt_romfs_file silk_romfs_files[];
extern const uint32_t silk_romfs_count;
extern const char *const silk_image_names[];
extern const char silk_game_version[];
extern const rt_literal silk_literals[];
extern const uint32_t silk_literal_count;
extern const rt_typeref silk_typerefs[];
extern const uint32_t silk_typeref_count;
extern rt_patch_class silk_patch_classes[];
extern const uint32_t silk_patch_class_count;
extern const rt_plugin silk_plugins[];
extern const uint32_t silk_plugin_count;
extern const char *const silk_asm_names[];
}

// ---------------------------------------------------------------- mod object layouts

struct ModObj : Il2CppArray {
    const rt_modtype *desc;
};

struct ModComponent : ModObj {
    obj go;       // GameObject this virtual component lives on
    obj host;     // real Unity component (SlideSurface) that represents it
    uint8_t enabled, awoken, started, destroyed;
    uint32_t _pad;
    obj coroutines;  // rt-internal list (object[])
};

struct ModPlugin : ModComponent {
    obj logger;
    obj config;
    int32_t plugin_index;
};

struct ModException : ModObj {
    obj message;
    obj inner;
};

struct ModDelegate : ModObj {
    void *fn;
    obj target;
};

// ---------------------------------------------------------------- core API

bool rt_ready();
[[noreturn]] void rt_unsupported(const char *what);
[[noreturn]] void rt_throw(obj ex);
[[noreturn]] void rt_rethrow();
[[noreturn]] __attribute__((noinline)) void rt_throw_nre();
[[noreturn]] void rt_throw_cast(obj o);
[[noreturn]] void rt_throw_index();
obj rt_exception();
obj rt_take_exception();
void rt_report_exception(const char *where);

__attribute__((always_inline)) inline obj rt_nc(obj o) {
    if (__builtin_expect(o == nullptr, 0)) rt_throw_nre();
    return o;
}

// Object used as an instance of a mod-defined class: must really be one (never scribble on game objects).
extern void *g_rt_objarr_klass;
inline obj rt_mc(obj o) {
    if (__builtin_expect(o == nullptr, 0)) rt_throw_nre();
    if (__builtin_expect(o->klass != g_rt_objarr_klass, 0)) rt_throw_cast(o);
    return o;
}

template <typename T>
inline T rt_div(T a, T b) {
    if (b == 0) rt_unsupported("division by zero");
    if (b == (T)-1) return (T)(0 - a);
    return a / b;
}
template <typename T>
inline T rt_rem(T a, T b) {
    if (b == 0) rt_unsupported("division by zero");
    if (b == (T)-1) return 0;
    return a % b;
}
template <typename T, typename F>
inline T rt_f2i(F f) {
    if (f != f) return 0;
    if (f >= (F)__INT64_MAX__) return (T)__INT64_MAX__;
    if (f <= -(F)__INT64_MAX__) return (T)(-__INT64_MAX__ - 1);
    return (T)(int64_t)f;
}

// exceptions: setjmp-style handlers
struct rt_jmpbuf {
    uint64_t regs[22];
};
extern "C" __attribute__((returns_twice)) int rt_setjmp(rt_jmpbuf *);
extern "C" [[noreturn]] void rt_longjmp(rt_jmpbuf *, int);
struct rt_handler {
    rt_jmpbuf jb;
    rt_handler *prev;
#ifdef SILKNX_TRACE
    uintptr_t pushed_by;  // where rt_push was called (debug: find leaked handlers)
#endif
};
void rt_push(rt_handler *h);
void rt_pop(rt_handler *h);
#define RT_TRY(h) (rt_push(&(h)), rt_setjmp(&(h).jb) != 0)
// Boundary between the game and mod code: catches both mod (setjmp) and game (C++) exceptions.
void rt_unwind_to(rt_handler *h);
void rt_caught_native(const char *where);
#define RT_GUARD_BEGIN { rt_handler __guard; if (!RT_TRY(__guard)) { try {
#define RT_GUARD_END } catch (...) { rt_unwind_to(&__guard); rt_caught_native(__func__); } rt_pop(&__guard); } \
    else { rt_report_exception(__func__); } }

